// Reference data: data/aip.js, data/vfr.js, data/sun.js (generated by the Python tools from the
// eAIP) → typed JSON for the client (src/data/ref/*.json) and the SQL migration that seeds the
// ref_* tables for the API (api/_lib/migrations/002_ref_<airac>.ts, a module exporting the SQL).
//
//   npm run ref            (= tsx tools/build_ref.ts)
//   npm run ref -- --check (exit 1 if the outputs are stale; used by the unit tests)
//
// A new AIRAC gets a NEW migration file (002 stays as applied); bump MIGRATION below.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';

import { adHoursFromAip, type AipHoursText } from '../src/calc/adHours.js';
import type {
  RefAerodrome,
  RefAirac,
  RefAirspace,
  RefArea,
  RefAtcUnit,
  RefFis,
  RefRunway,
  RefSunTable,
  RefVfrPoint,
  RefVfrRoute,
} from '../src/shared/ref.js';
import { buildRunways, loadParsedRunways } from './build_ref_runways.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT = path.join(ROOT, 'src', 'data', 'ref');
const MIGRATION = path.join(ROOT, 'api', '_lib', 'migrations', '002_ref_2609.ts');
// 002 is applied and no longer regenerated (its VFR points were incomplete): set false with a new MIGRATION file.
const MIGRATION_FROZEN = true;
// The AIRAC's complete VFR reporting points (tools/parse_vfr.ts + tools/build_vfr.py), replacing the ref_waypoints
// rows of 002. null when MIGRATION itself is regenerated (a new AIRAC).
const VFR_MIGRATION: string | null = path.join(ROOT, 'api', '_lib', 'migrations', '048_ref_vfr_points_2609.ts');
// Runway physical data and declared distances (tools/runways.json from tools/parse_runways.py) for the same
// AIRAC, loaded after 002 (which, as applied, has the runway directions with null distances).
const RUNWAY_MIGRATION = path.join(ROOT, 'api', '_lib', 'migrations', '005_ref_runways_2609.ts');
// Operational hours and handling (AD 2.3, AD 1.6.N.3/4: tools/ad_hours.json from tools/extract_ad_hours.ts),
// added to the AIRAC's aerodrome records after 002 (which, as applied, has none).
const HOURS_MIGRATION = path.join(ROOT, 'api', '_lib', 'migrations', '012_ref_ad_hours_2609.ts');
const HOURS_JSON = path.join(ROOT, 'tools', 'ad_hours.json');
// ENR 5.1 / 5.2 / 5.3 areas (tools/enr5_areas.json from tools/parse_enr5.ts): the ref_areas table (created
// by this migration if missing) and src/data/ref/areas.json.
const AREAS_MIGRATION = path.join(ROOT, 'api', '_lib', 'migrations', '017_ref_areas_2609.ts');
const AREAS_JSON = path.join(ROOT, 'tools', 'enr5_areas.json');

function loadWindowGlobal(file: string, name: string): any {
  const ctx: any = { window: {} };
  vm.runInNewContext(fs.readFileSync(path.join(ROOT, file), 'utf8'), ctx);
  return ctx.window[name];
}

const MONTHS: Record<string, string> = {
  JAN: '01',
  FEB: '02',
  MAR: '03',
  APR: '04',
  MAY: '05',
  JUN: '06',
  JUL: '07',
  AUG: '08',
  SEP: '09',
  OCT: '10',
  NOV: '11',
  DEC: '12',
};
const slug = (s: string) =>
  s
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

export function buildRef() {
  const AIP = loadWindowGlobal('data/aip.js', 'AIP');
  const VFR = loadWindowGlobal('data/vfr.js', 'VFR');
  const SUN = loadWindowGlobal('data/sun.js', 'SUN');

  const m = /AMDT (\d\d)\/(\d\d) \(wef (\d+) ([A-Z]{3}) (\d{4})\)/.exec(AIP.airac);
  if (!m) throw new Error('cannot parse AIRAC: ' + AIP.airac);
  const airac: RefAirac = {
    id: m[2] + m[1],
    name: AIP.airac,
    effective: `${m[5]}-${MONTHS[m[4]]}-${m[3].padStart(2, '0')}`,
  };

  const aerodromes: RefAerodrome[] = AIP.aerodromes.map((a: any) => ({
    id: a.id,
    icao: a.icao ?? null,
    name: a.name,
    lat: a.lat,
    lon: a.lon,
    elevFt: a.elevFt ?? null,
    runways: a.runways,
    freqs: a.freqs.map((f: any) => ({
      service: f.service,
      callsign: f.callsign,
      mhz: f.mhz,
      role: f.role,
      remark: f.remark ?? '',
    })),
    zones: a.zones,
    water: !!a.water,
    source: a.source ?? '',
    notes: a.notes ?? '',
  }));

  // One row per runway direction, as loaded by migration 002 (no physical data). Kept unchanged because 002
  // is applied; the full records (`runways`) come from the AIP runway tables and are loaded by RUNWAY_MIGRATION.
  const baseRunways: RefRunway[] = [];
  for (const a of aerodromes) {
    for (const pair of a.runways) {
      const ends = pair.split('/').map((s) => s.trim());
      if (ends.length !== 2) continue;
      ends.forEach((d, i) => {
        const n = parseInt(d, 10);
        baseRunways.push({
          aerodromeId: a.id,
          designator: d,
          reciprocal: ends[1 - i],
          headingMagDeg: isFinite(n) ? n * 10 : NaN,
          headingTrueDeg: null,
          lengthM: null,
          widthM: null,
          surface: null,
          toraM: null,
          todaM: null,
          asdaM: null,
          ldaM: null,
          slopePct: null,
          thresholdElevFt: a.elevFt,
        });
      });
    }
  }

  const { runways, warnings: runwayWarnings } = buildRunways(aerodromes, loadParsedRunways(ROOT), airac.effective);

  const seenAs = new Map<string, number>();
  const airspaces: RefAirspace[] = AIP.airspace.map((v: any) => {
    const base = slug(v.name);
    const k = (seenAs.get(base) || 0) + 1;
    seenAs.set(base, k);
    return {
      id: `${base}-${k}`,
      name: v.name,
      kind: v.kind,
      class: v.class ?? '',
      sector: v.sector ?? '',
      lower: v.lower,
      upper: v.upper,
      polygon: v.polygon,
      units: v.units ?? [],
      note: v.note ?? '',
      source: v.source ?? '',
    };
  });

  const fis: RefFis = { units: AIP.fis.units, boundary: AIP.fis.boundary, source: AIP.fis.source ?? '' };

  const seenPt = new Map<string, number>();
  const vfrPoints: RefVfrPoint[] = VFR.points.map((p: any) => {
    const base = `${p.chart}/${p.name}`;
    const k = (seenPt.get(base) || 0) + 1;
    seenPt.set(base, k);
    return {
      id: k === 1 ? base : `${base}#${k}`,
      name: p.name,
      lat: p.lat,
      lon: p.lon,
      chart: p.chart,
      src: p.src,
      charts: p.charts ?? [],
      sources: p.sources ?? [],
    };
  });

  const seenRt = new Map<string, number>();
  const vfrRoutes: RefVfrRoute[] = VFR.routes.map((r: any) => {
    const base = `${r.chart}:${r.a}>${r.b}`;
    const k = (seenRt.get(base) || 0) + 1;
    seenRt.set(base, k);
    return {
      id: k === 1 ? base : `${base}#${k}`,
      chart: r.chart,
      a: r.a,
      b: r.b,
      minFt: r.min,
      maxFt: r.max,
      oneway: !!r.oneway,
    };
  });

  const atcUnits: RefAtcUnit[] = [];
  for (const a of aerodromes) {
    const groups = new Map<string, RefAtcUnit>();
    for (const f of a.freqs) {
      const cs = f.callsign || f.service;
      if (!groups.has(cs))
        groups.set(cs, {
          id: `ad:${a.id}:${cs}`,
          kind: 'aerodrome',
          owner: a.id,
          callsign: cs,
          service: f.service,
          freqs: [],
        });
      groups.get(cs)!.freqs.push({ mhz: f.mhz, role: f.role, remark: f.remark });
    }
    atcUnits.push(...groups.values());
  }
  const seenUnit = new Set<string>();
  for (const v of airspaces) {
    for (const u of v.units) {
      const id = `as:${v.name}:${u.callsign}`;
      if (seenUnit.has(id)) continue;
      seenUnit.add(id);
      atcUnits.push({
        id,
        kind: 'airspace',
        owner: v.name,
        callsign: u.callsign,
        service: u.callsign.split(/\s+/).pop() || '',
        freqs: u.freqs.map((mhz, i) => ({
          mhz,
          role: i === 0 ? 'primary' : 'secondary',
          remark: u.hours ? `Hours ${u.hours}` : '',
        })),
      });
    }
  }
  for (const u of fis.units) {
    atcUnits.push({
      id: `fis:${u.callsign}`,
      kind: 'fis',
      owner: 'FIS',
      callsign: u.callsign,
      service: 'INFO',
      freqs: u.freqs.map((mhz, i) => ({ mhz, role: i === 0 ? 'primary' : 'secondary', remark: `${u.side} sector` })),
    });
  }

  const sun: Record<string, RefSunTable> = SUN;

  // The aerodromes as shipped to the client and loaded by HOURS_MIGRATION: with their operational hours.
  // `aerodromes` (002) stays without them.
  const rawHours: Record<string, AipHoursText> = fs.existsSync(HOURS_JSON)
    ? JSON.parse(fs.readFileSync(HOURS_JSON, 'utf8'))
    : {};
  const aerodromesFull: RefAerodrome[] = aerodromes.map((a) =>
    rawHours[a.id] ? { ...a, hours: adHoursFromAip(rawHours[a.id]) } : a,
  );
  const areas: RefArea[] = fs.existsSync(AREAS_JSON) ? JSON.parse(fs.readFileSync(AREAS_JSON, 'utf8')) : [];
  return {
    airac,
    aerodromes,
    aerodromesFull,
    baseRunways,
    runways,
    runwayWarnings,
    airspaces,
    fis,
    vfrPoints,
    vfrRoutes,
    atcUnits,
    sun,
    areas,
  };
}

const q = (s: string) => `'${s.replace(/'/g, "''")}'`;
const j = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;
const n = (v: number | null) => (v === null || !isFinite(v) ? 'NULL' : String(v));

function chunks<T>(xs: T[], size = 100): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < xs.length; i += size) out.push(xs.slice(i, i + size));
  return out;
}

export function refSql(r: ReturnType<typeof buildRef>): string {
  const A = q(r.airac.id);
  const L: string[] = [
    `-- Generated by tools/build_ref.ts from data/aip.js, data/vfr.js, data/sun.js. Do not edit by hand.`,
    `-- Reference data for ${r.airac.name}.`,
    `UPDATE ref_airac SET current = FALSE;`,
    `INSERT INTO ref_airac (id, name, effective, current, loaded) VALUES (${A}, ${q(r.airac.name)}, ${q(r.airac.effective)}, TRUE, 0);`,
  ];
  const ins = (table: string, cols: string, rows: string[]) => {
    for (const c of chunks(rows)) L.push(`INSERT INTO ${table} (${cols}) VALUES\n${c.join(',\n')};`);
  };
  ins(
    'ref_aerodromes',
    'airac, id, icao, name, lat, lon, doc',
    r.aerodromes.map(
      (a) => `(${A}, ${q(a.id)}, ${a.icao ? q(a.icao) : 'NULL'}, ${q(a.name)}, ${n(a.lat)}, ${n(a.lon)}, ${j(a)})`,
    ),
  );
  ins(
    'ref_runways',
    'airac, aerodrome_id, designator, doc',
    r.baseRunways.map((w) => `(${A}, ${q(w.aerodromeId)}, ${q(w.designator)}, ${j(w)})`),
  );
  ins(
    'ref_airspaces',
    'airac, id, name, kind, doc',
    r.airspaces.map((v) => `(${A}, ${q(v.id)}, ${q(v.name)}, ${q(v.kind)}, ${j(v)})`),
  );
  L.push(`INSERT INTO ref_fis (airac, doc) VALUES (${A}, ${j(r.fis)});`);
  ins(
    'ref_waypoints',
    'airac, id, name, lat, lon, chart, doc',
    r.vfrPoints.map((p) => `(${A}, ${q(p.id)}, ${q(p.name)}, ${n(p.lat)}, ${n(p.lon)}, ${q(p.chart)}, ${j(p)})`),
  );
  ins(
    'ref_vfr_routes',
    'airac, id, chart, a, b, doc',
    r.vfrRoutes.map((x) => `(${A}, ${q(x.id)}, ${q(x.chart)}, ${q(x.a)}, ${q(x.b)}, ${j(x)})`),
  );
  ins(
    'ref_atc_units',
    'airac, id, kind, owner, doc',
    r.atcUnits.map((u) => `(${A}, ${q(u.id)}, ${q(u.kind)}, ${q(u.owner)}, ${j(u)})`),
  );
  ins(
    'ref_sun',
    'airac, icao, doc',
    Object.entries(r.sun).map(([icao, t]) => `(${A}, ${q(icao)}, ${j(t)})`),
  );
  return L.join('\n') + '\n';
}

/** Replaces the AIRAC's VFR reporting points (migration 048). */
export function vfrPointsSql(r: ReturnType<typeof buildRef>): string {
  const A = q(r.airac.id);
  const L: string[] = [
    `-- Generated by tools/build_ref.ts from data/vfr.js (tools/parse_vfr.ts, tools/build_vfr.py). Do not edit by hand.`,
    `-- VFR reporting points for ${r.airac.name}: every VFR chart, its coordinate tables and the heliports' reporting points.`,
    `DELETE FROM ref_waypoints WHERE airac = ${A};`,
  ];
  for (const c of chunks(r.vfrPoints)) {
    L.push(
      `INSERT INTO ref_waypoints (airac, id, name, lat, lon, chart, doc) VALUES\n${c.map((p) => `(${A}, ${q(p.id)}, ${q(p.name)}, ${n(p.lat)}, ${n(p.lon)}, ${q(p.chart)}, ${j(p)})`).join(',\n')};`,
    );
  }
  return L.join('\n') + '\n';
}

/** Replaces the AIRAC's runway rows with the full records (migration 005). */
export function runwaySql(r: ReturnType<typeof buildRef>): string {
  const A = q(r.airac.id);
  const L: string[] = [
    `-- Generated by tools/build_ref.ts from tools/runways.json (tools/parse_runways.py, eAIP AD 2.12/2.13, AD 1.6.N.12/13). Do not edit by hand.`,
    `-- Runway physical characteristics and declared distances for ${r.airac.name}.`,
    `DELETE FROM ref_runways WHERE airac = ${A};`,
  ];
  for (const c of chunks(r.runways)) {
    L.push(
      `INSERT INTO ref_runways (airac, aerodrome_id, designator, doc) VALUES\n${c.map((w) => `(${A}, ${q(w.aerodromeId)}, ${q(w.designator)}, ${j(w)})`).join(',\n')};`,
    );
  }
  return L.join('\n') + '\n';
}

/** Adds the operational hours to the AIRAC's aerodrome records (migration 012). */
export function hoursSql(r: ReturnType<typeof buildRef>): string {
  const A = q(r.airac.id);
  const L: string[] = [
    `-- Generated by tools/build_ref.ts from tools/ad_hours.json (tools/extract_ad_hours.ts, eAIP AD 2.3, AD 1.6.N.3/4). Do not edit by hand.`,
    `-- Aerodrome operational hours and handling for ${r.airac.name}: the AIP text verbatim and its parse (src/calc/adHours.ts).`,
  ];
  for (const a of r.aerodromesFull) {
    if (!a.hours) continue;
    L.push(
      `UPDATE ref_aerodromes SET doc = doc || jsonb_build_object('hours', ${j(a.hours)}) WHERE airac = ${A} AND id = ${q(a.id)};`,
    );
  }
  return L.join('\n') + '\n';
}

/** The ENR 5 areas of the AIRAC (migration 017; the table is created the first time). */
export function areasSql(r: ReturnType<typeof buildRef>): string {
  const A = q(r.airac.id);
  const L: string[] = [
    `-- Generated by tools/build_ref.ts from tools/enr5_areas.json (tools/parse_enr5.ts, eAIP ENR 5.1, 5.2, 5.3). Do not edit by hand.`,
    `-- Prohibited, restricted, danger, military exercise / training and local flying areas for ${r.airac.name}.`,
    `CREATE TABLE IF NOT EXISTS ref_areas (`,
    `  airac TEXT NOT NULL REFERENCES ref_airac(id) ON DELETE CASCADE,`,
    `  id TEXT NOT NULL,`,
    `  kind TEXT NOT NULL,`,
    `  name TEXT NOT NULL,`,
    `  doc JSONB NOT NULL,`,
    `  PRIMARY KEY (airac, id)`,
    `);`,
    `DELETE FROM ref_areas WHERE airac = ${A};`,
  ];
  for (const c of chunks(r.areas)) {
    L.push(
      `INSERT INTO ref_areas (airac, id, kind, name, doc) VALUES\n${c.map((a) => `(${A}, ${q(a.id)}, ${q(a.kind)}, ${q(a.name)}, ${j(a)})`).join(',\n')};`,
    );
  }
  return L.join('\n') + '\n';
}

export function outputs(): Record<string, string> {
  const r = buildRef();
  const json = (v: unknown) => JSON.stringify(v) + '\n';
  const out: Record<string, string> = {
    [path.join(OUT, 'airac.json')]: JSON.stringify(r.airac, null, 2) + '\n',
    [path.join(OUT, 'aerodromes.json')]: json(r.aerodromesFull),
    [path.join(OUT, 'runways.json')]: json(r.runways),
    [path.join(OUT, 'airspaces.json')]: json(r.airspaces),
    [path.join(OUT, 'fis.json')]: json(r.fis),
    [path.join(OUT, 'vfr-points.json')]: json(r.vfrPoints),
    [path.join(OUT, 'vfr-routes.json')]: json(r.vfrRoutes),
    [path.join(OUT, 'atc-units.json')]: json(r.atcUnits),
    [path.join(OUT, 'sun.json')]: json(r.sun),
    [path.join(OUT, 'areas.json')]: json(r.areas),
    [RUNWAY_MIGRATION]: `// Generated by tools/build_ref.ts. Do not edit by hand.\nconst sql: string = ${JSON.stringify(runwaySql(r))};\nexport default sql;\n`,
    [AREAS_MIGRATION]: `// Generated by tools/build_ref.ts. Do not edit by hand.\nconst sql: string = ${JSON.stringify(areasSql(r))};\nexport default sql;\n`,
    [HOURS_MIGRATION]: `// Generated by tools/build_ref.ts. Do not edit by hand.\nconst sql: string = ${JSON.stringify(hoursSql(r))};\nexport default sql;\n`,
  };
  const ts = (sql: string) =>
    `// Generated by tools/build_ref.ts. Do not edit by hand.\nconst sql: string = ${JSON.stringify(sql)};\nexport default sql;\n`;
  if (!MIGRATION_FROZEN) out[MIGRATION] = ts(refSql(r));
  if (VFR_MIGRATION) out[VFR_MIGRATION] = ts(vfrPointsSql(r));
  return out;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const out = outputs();
  const check = process.argv.includes('--check');
  for (const w of buildRef().runwayWarnings) console.warn('runways:', w);
  let stale = 0;
  for (const [f, text] of Object.entries(out)) {
    const cur = fs.existsSync(f) ? fs.readFileSync(f, 'utf8') : null;
    if (cur === text) continue;
    stale++;
    if (check) console.error('stale:', path.relative(ROOT, f));
    else {
      fs.mkdirSync(path.dirname(f), { recursive: true });
      fs.writeFileSync(f, text);
      console.log('wrote', path.relative(ROOT, f));
    }
  }
  if (check && stale) process.exit(1);
  if (!check && !stale) console.log('reference data up to date');
}
